# Generated by release/homebrew/formula.sh of the wolfpack repository for each release.
class Wolfpack < Formula
  desc "Statically typed language that compiles to readable TypeScript, Go and Rust"
  homepage "https://github.com/realfamousbae/wolfpack"
  version "0.3.0"
  license any_of: ["MIT", "Apache-2.0"]

  on_macos do
    url "https://github.com/realfamousbae/wolfpack/releases/download/v0.3.0/wolfpack-macos-universal.tar.gz"
    sha256 "2a325add785c24a4c23523418b3c88cacbdac6ec01922c44a89eab7d51a2b4df"
  end

  on_linux do
    on_intel do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.3.0/wolfpack-linux-x64.tar.gz"
      sha256 "950791dbdf8a4cd1d5a628fd5e9419cda2cb1ac2d494e02397ee7cffccec175e"
    end
    on_arm do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.3.0/wolfpack-linux-arm64.tar.gz"
      sha256 "e81c6bd23ffecf31db16c0a980a59a242ca481b11f0d0a85f2b909c940369c05"
    end
  end

  def install
    bin.install "wolf"
  end

  def caveats
    <<~EOS
      wolf runs programs in its own VM without other tools (wolf run --vm).
      To build and run them as TypeScript, Go or Rust, install those tools with:
        wolf setup
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/wolf --version")
    system bin/"wolf", "new", "hello"
    assert_equal "Hello, wolfpack!\n", shell_output("cd hello && #{bin}/wolf run --vm")
  end
end
